package com.bank.adder;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class LongAdderTest {

    static final int THREADS = 100;
    static final int OPS = 100_000;

    // ═══ LongAdder: exact total after all threads finish ═══
    @Test
    void longAdder_exactAfterCompletion() throws InterruptedException {
        LongAdder adder = new LongAdder();
        CountDownLatch latch = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < OPS; i++) adder.increment();
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(adder.sum()).isEqualTo((long) THREADS * OPS);  // exact!
    }

    // ═══ Performance: LongAdder vs AtomicLong ═══
    @Test
    void performance_adderVsAtomic() throws InterruptedException {
        // AtomicLong:
        AtomicLong atomicCounter = new AtomicLong(0);
        long atomicTime = benchmark(() -> atomicCounter.incrementAndGet());

        // LongAdder:
        LongAdder adderCounter = new LongAdder();
        long adderTime = benchmark(() -> adderCounter.increment());

        System.out.println("AtomicLong: " + atomicTime + "ms, LongAdder: " + adderTime + "ms");
        System.out.println("Speedup: " + (atomicTime / Math.max(adderTime, 1)) + "x");
        // LongAdder typically 2-5x faster!
    }

    long benchmark(Runnable op) throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(THREADS);
        long start = System.currentTimeMillis();
        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < OPS; i++) op.run();
                latch.countDown();
            }).start();
        }
        latch.await();
        return System.currentTimeMillis() - start;
    }

    // ═══ LongAccumulator: custom function (max) ═══
    @Test
    void longAccumulator_trackMax() throws InterruptedException {
        LongAccumulator maxTracker = new LongAccumulator(Math::max, 0);
        CountDownLatch latch = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    maxTracker.accumulate(ThreadLocalRandom.current().nextLong(10000));
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(maxTracker.get()).isGreaterThan(9000);  // near 10000!
    }

    // ═══ sumThenReset: read and reset atomically per cell ═══
    @Test
    void sumThenReset() {
        LongAdder adder = new LongAdder();
        adder.add(100);
        adder.add(200);

        long total = adder.sumThenReset();
        assertThat(total).isEqualTo(300);
        assertThat(adder.sum()).isEqualTo(0);  // reset!
    }
}
